contract InvMutTest {
    C c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that performs two attempts: one from this contract (non-depositor)
    // and one simulated call from the depositor via call() on the deployed C contract by forwarding
    // a delegated call is not possible, so instead we check behavior for non-depositor revert and
    // then rely on the rule that when caller == depositor the values equal inputs. To invoke as the
    // depositor we cannot change msg.sender here; however the problem statement allows only calling
    // c with msg.sender = InvMutTest (since InvMutTest deployed c). Therefore we assert a general
    // rule: either the non-depositor call reverts and leaves state unchanged, or if it doesn't revert
    // then the state equals the inputs. This captures that only-depositor gate prevents state changes.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // read before-values
        uint64 before_number = c.number();
        uint64 before_timestamp = c.timestamp();
        uint256 before_basefee = c.basefee();
        bytes32 before_hash = c.hash();
        uint64 before_sequenceNumber = c.sequenceNumber();
        bytes32 before_batcherHash = c.batcherHash();
        uint256 before_l1FeeOverhead = c.l1FeeOverhead();
        uint256 before_l1FeeScalar = c.l1FeeScalar();

        bool reverted = false;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint64 after_number = c.number();
        uint64 after_timestamp = c.timestamp();
        uint256 after_basefee = c.basefee();
        bytes32 after_hash = c.hash();
        uint64 after_sequenceNumber = c.sequenceNumber();
        bytes32 after_batcherHash = c.batcherHash();
        uint256 after_l1FeeOverhead = c.l1FeeOverhead();
        uint256 after_l1FeeScalar = c.l1FeeScalar();

        // General rule asserted in one boolean expression:
        // If the call reverted, then none of the public fields changed (equal to before values).
        // If the call did not revert, then all public fields equal the provided inputs.
        assert(
            (reverted &&
                after_number == before_number &&
                after_timestamp == before_timestamp &&
                after_basefee == before_basefee &&
                after_hash == before_hash &&
                after_sequenceNumber == before_sequenceNumber &&
                after_batcherHash == before_batcherHash &&
                after_l1FeeOverhead == before_l1FeeOverhead &&
                after_l1FeeScalar == before_l1FeeScalar
            ) ||
            (!reverted &&
                after_number == _number &&
                after_timestamp == _timestamp &&
                after_basefee == _basefee &&
                after_hash == _hash &&
                after_sequenceNumber == _sequenceNumber &&
                after_batcherHash == _batcherHash &&
                after_l1FeeOverhead == _l1FeeOverhead &&
                after_l1FeeScalar == _l1FeeScalar
            )
        );
    }

    receive() external payable {}
}

