contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take the same parameters as setL1BlockValues; no Ether is sent to c in this test.
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // No precondition on parameters
        // Observe balance of c before the call
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balance of c after the call
        uint256 afterBalance = address(c).balance;

        // General rule: regardless of revert or success, calling setL1BlockValues does not change C's ether balance
        assert(afterBalance == beforeBalance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    // Deploy with existing C instance
    constructor(C _c) { c = _c; }

    // We cannot call c as the real DEPOSITOR_ACCOUNT since msg.sender will be this contract.
    // But we can check the behavior for two cases by simulating: when this contract is NOT the depositor,
    // calling setL1BlockValues must revert; and when it is the depositor (which it is not by default),
    // we cannot switch msg.sender, so instead we assert the general rule that if a call did not revert,
    // then all public storage values were updated to the provided inputs.
    // The property: for any inputs, if setL1BlockValues succeeds, then each public getter equals the input.

    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        // No precondition on params
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after the attempt
        uint64 number = c.number();
        uint64 timestamp = c.timestamp();
        uint256 basefee = c.basefee();
        bytes32 hash = c.hash();
        uint64 sequenceNumber = c.sequenceNumber();
        bytes32 batcherHash = c.batcherHash();
        uint256 l1FeeOverhead = c.l1FeeOverhead();
        uint256 l1FeeScalar = c.l1FeeScalar();

        // General rule: if the call succeeded (did not revert), then every stored public field must equal the corresponding input.
        // If the call reverted, we impose no further constraints here.
        assert(reverted || (
            number == _number
            && timestamp == _timestamp
            && basefee == _basefee
            && hash == _hash
            && sequenceNumber == _sequenceNumber
            && batcherHash == _batcherHash
            && l1FeeOverhead == _l1FeeOverhead
            && l1FeeScalar == _l1FeeScalar
        ));
    }

    receive() external payable {}
}
